selector_to_html = {"a[href=\"../getting_started/multi-backend-prebuilt-docker-image-install/install-spacemit.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab SpacemiT\uff08\u8fdb\u8fed\u65f6\u7a7a\uff09<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/main/third_party/spacemit/\">spacemit</a>3.6<a class=\"headerlink\" href=\"#spacemit-spacemit3-6\" title=\"Link to this heading\">#</a></h1><h2>1. Quick start<a class=\"headerlink\" href=\"#quick-start\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the image (x64 emulation environment)<a class=\"headerlink\" href=\"#use-the-image-x64-emulation-environment\" title=\"Link to this heading\">#</a></h3>", "a[href=\"../getting_started/multi-backend-prebuilt-docker-image-install/install-xpu.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab KLX <a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/main/third_party/xpu/\">xpu</a>3.6<a class=\"headerlink\" href=\"#klx-xpu3-6\" title=\"Link to this heading\">#</a></h1><h2>1. Quick start<a class=\"headerlink\" href=\"#quick-start\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the image (P800)<a class=\"headerlink\" href=\"#use-the-image-p800\" title=\"Link to this heading\">#</a></h3>", "a[href=\"../getting_started/multi-backend-prebuilt-docker-image-install/install-ppu.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab T-Head\uff08\u5e73\u5934\u54e5\uff09<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/main/third_party/ppu/\">ppu</a>3.6<a class=\"headerlink\" href=\"#t-head-ppu3-6\" title=\"Link to this heading\">#</a></h1><h2>1. Quick start<a class=\"headerlink\" href=\"#quick-start\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the image (810E|890P)<a class=\"headerlink\" href=\"#use-the-image-810e-890p\" title=\"Link to this heading\">#</a></h3>", "a[href=\"../getting_started/multi-backend-prebuilt-docker-image-install/install-amd.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab AMD <a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/main/third_party/amd/\">amd</a><a class=\"headerlink\" href=\"#amd-amd\" title=\"Link to this heading\">#</a></h1><h2>1. Quick start<a class=\"headerlink\" href=\"#quick-start\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the image (for Triton 3.6)<a class=\"headerlink\" href=\"#use-the-image-for-triton-3-6\" title=\"Link to this heading\">#</a></h3>", "a[href=\"../getting_started/install-arm64-cpu.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Install on Arm64 CPU<a class=\"headerlink\" href=\"#install-on-arm64-cpu\" title=\"Link to this heading\">#</a></h1><p>Before installing the FlagTree on Arm64 CPU, please read the following notes:</p>", "a[href=\"../user_guide/use-tle-cpu.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Use TLE-CPU<a class=\"headerlink\" href=\"#use-tle-cpu\" title=\"Link to this heading\">#</a></h1><p>This section introduces how to use TLE-CPU. TLE-CPU is available on trition_3.3.x branch.</p><p>TLE-CPU allows a unified programming paradigm covering diverse edge-side CPU compute power. Extends TLE\u2019s philosophy of \u201clayering hardware deep optimizations on top of <code class=\"docutils literal notranslate\"><span class=\"pre\">@triton.jit</span></code>\u201d to CPUs. Targeting the fragmented CPU ecosystem for edge AI (Arm64 / RISC-V / x86 with multiple coexisting ISAs), it uses the same Triton programming model and integration framework to support diverse ISAs: programming model and correctness are shared across ISAs (plain Triton lands on any ISA via LLVM), while each ISA\u2019s high-performance implementation (intrinsic / C runtime) is contributed separately. Model code is routed to the corresponding ISA implementation through the operator library (FlagGems) vendor dispatch, eliminating the need to be aware of the specific ISA. The differences between CPU and GPU dictate that it requires an independent extension surface:</p>", "a[href=\"../getting_started/multi-backend-prebuilt-docker-image-install/install-tsingmicro.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab Tsingmicro\uff08\u6e05\u5fae\u667a\u80fd\uff09<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/main/third_party/tsingmicro/\">tsingmicro</a>3.6<a class=\"headerlink\" href=\"#tsingmicro-tsingmicro3-6\" title=\"Link to this heading\">#</a></h1><h2>1. Quick start<a class=\"headerlink\" href=\"#quick-start\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the image (TX81)<a class=\"headerlink\" href=\"#use-the-image-tx81\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#flagtree-0-7-0-release\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">FlagTree 0.7.0 Release<a class=\"headerlink\" href=\"#flagtree-0-7-0-release\" title=\"Link to this heading\">#</a></h1>", "a[href=\"../getting_started/multi-backend-prebuilt-docker-image-install/install-iluvatar.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab ILUVATAR\uff08\u5929\u6570\u667a\u82af\uff09<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/main/third_party/iluvatar/\">iluvatar</a>3.6<a class=\"headerlink\" href=\"#iluvatar-iluvatar3-6\" title=\"Link to this heading\">#</a></h1><h2>1. Quick start<a class=\"headerlink\" href=\"#quick-start\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the image (BI-V150)<a class=\"headerlink\" href=\"#use-the-image-bi-v150\" title=\"Link to this heading\">#</a></h3>", "a[href=\"../getting_started/multi-backend-prebuilt-docker-image-install/install-tileir.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab NVIDIA TileIR <a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/main/third_party/tileir/\">tileir</a>3.6<a class=\"headerlink\" href=\"#nvidia-tileir-tileir3-6\" title=\"Link to this heading\">#</a></h1><h2>1. Quick start<a class=\"headerlink\" href=\"#quick-start\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the image (Hopper/Blackwell)<a class=\"headerlink\" href=\"#use-the-image-hopper-blackwell\" title=\"Link to this heading\">#</a></h3><p>This image can also be used for the <code class=\"docutils literal notranslate\"><span class=\"pre\">nvidia</span></code> backend.</p>", "a[href=\"../getting_started/multi-backend-prebuilt-docker-image-install/install-rpu.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab Huixi Intelligence\uff08\u8f89\u7fb2\u667a\u80fd\uff09<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/main/third_party/rpu/\">rpu</a>3.6<a class=\"headerlink\" href=\"#huixi-intelligence-rpu3-6\" title=\"Link to this heading\">#</a></h1><p>The <strong>Rhino RPU</strong> is the AI accelerator inside Huixi Intelligence\u2019s \u5149\u81f3 R1 SoC\n(<a class=\"reference external\" href=\"https://www.rhino.auto/\">rhino.auto</a>). Unlike the CPU/GPU backends, the RPU\nbackend has <strong>no preinstalled image and no CPU simulator</strong> \u2014 it compiles and\nruns only on a physical R1 SoC board, and its driver, runtime, and toolchain are\nobtained from the vendor. Build and test directly on the board.</p>", "a[href=\"../getting_started/multi-backend-prebuilt-docker-image-install/install-sunrise.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab Sunrise\uff08\u66e6\u671b\u82af\u79d1\uff09<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/main/third_party/sunrise/\">sunrise</a>3.6<a class=\"headerlink\" href=\"#sunrise-sunrise3-6\" title=\"Link to this heading\">#</a></h1><h2>1. Quick start<a class=\"headerlink\" href=\"#quick-start\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the image (S2)<a class=\"headerlink\" href=\"#use-the-image-s2\" title=\"Link to this heading\">#</a></h3>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
